def operation(n):
    if n == 0:
        return 0
    removed_digit = n % 10
    remaining_number = n // 10
    return remaining_number + 3 * removed_digit

def generate_sequence(start_n, max_steps=50):
    sequence = [start_n]
    current_n = start_n
    seen = {start_n: 0}

    for i in range(1, max_steps + 1):
        current_n = operation(current_n)
        sequence.append(current_n)

        if current_n in seen:
            # Cycle detected
            cycle_start_index = seen[current_n]
            cycle_length = i - cycle_start_index
            return sequence, cycle_start_index, cycle_length

        seen[current_n] = i

    return sequence, -1, 0

# Test cases requested
tests = {
    "12345": 12345,
    "10000": 10000,
    "999": 999,
    "2": 2
}

results = {}
for name, n in tests.items():
    seq, start_idx, length = generate_sequence(n)
    results[name] = (seq, start_idx, length)

# Print results in a readable format
for name, (seq, start_idx, length) in results.items():
    print(f"\n--- Test Case: {name} ---")
    print(f"Sequence (first 20 elements): {seq[:20]}...")
    if start_idx != -1:
        print(f"Cycle detected starting at index {start_idx} (value: {seq[start_idx]}) with length {length}.")
    else:
        print("No cycle found within the limit.")

